import{b as a,O as t,g as e,j as n}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":".gitignore 与提交规范","description":"","frontmatter":{},"headers":[],"relativePath":"git/collaboration/gitignore-commit/index.md","filePath":"Git操作手册/4.协作与进阶/03.gitignore与提交规范.md","lastUpdated":1781406415000}'),i={name:"git/collaboration/gitignore-commit/index.md"};function d(o,s,l,p,c,r){return t(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="gitignore-与提交规范" tabindex="-1">.gitignore 与提交规范 <a class="header-anchor" href="#gitignore-与提交规范" aria-label="Permalink to &quot;.gitignore 与提交规范&quot;">​</a></h1><blockquote><p>哪些文件不提交 / 提交信息怎么写，团队协作的基础约定</p></blockquote><h2 id="有些文件不该提交" tabindex="-1">有些文件不该提交 <a class="header-anchor" href="#有些文件不该提交" aria-label="Permalink to &quot;有些文件不该提交&quot;">​</a></h2><p>不是项目文件夹里的所有东西都要交给 Git 管理。以下三类文件应该忽略：</p><ol><li><strong>自动生成的文件</strong> — <code>node_modules/</code>、编译产物 <code>dist/</code>、<code>__pycache__/</code></li><li><strong>敏感信息</strong> — 包含密码和密钥的配置文件（<code>.env</code>、<code>secret.config</code>）</li><li><strong>系统和个人文件</strong> — macOS 的 <code>.DS_Store</code>、IDE 配置 <code>.vscode/</code>、日志文件 <code>*.log</code></li></ol><p>如果把这些文件提交到仓库，后果是：仓库体积膨胀、密钥泄露、团队成员用不同 IDE 互相污染。</p><h2 id="gitignore-忽略文件清单" tabindex="-1">.gitignore：忽略文件清单 <a class="header-anchor" href="#gitignore-忽略文件清单" aria-label="Permalink to &quot;.gitignore：忽略文件清单&quot;">​</a></h2><p>在项目根目录创建一个 <code>.gitignore</code> 文件，把不想跟踪的文件列进去：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 依赖目录</span></span>
<span class="line"><span>node_modules/</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 编译产物</span></span>
<span class="line"><span>dist/</span></span>
<span class="line"><span>build/</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 敏感配置</span></span>
<span class="line"><span>.env</span></span>
<span class="line"><span>*.pem</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 系统文件</span></span>
<span class="line"><span>.DS_Store</span></span>
<span class="line"><span>Thumbs.db</span></span>
<span class="line"><span></span></span>
<span class="line"><span># IDE 配置</span></span>
<span class="line"><span>.vscode/</span></span>
<span class="line"><span>.idea/</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 日志</span></span>
<span class="line"><span>*.log</span></span></code></pre></div><h3 id="匹配规则" tabindex="-1">匹配规则 <a class="header-anchor" href="#匹配规则" aria-label="Permalink to &quot;匹配规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规则</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td><code>文件夹名/</code></td><td>忽略这个文件夹</td><td><code>node_modules/</code></td></tr><tr><td><code>*.后缀</code></td><td>忽略所有此后缀的文件</td><td><code>*.log</code></td></tr><tr><td><code>!文件名</code></td><td>取反：不忽略这个文件</td><td><code>!important.log</code></td></tr><tr><td><code>**/文件夹</code></td><td>匹配任意层级的目录</td><td><code>**/__pycache__</code></td></tr><tr><td><code>/文件名</code></td><td>只忽略根目录下的</td><td><code>/config.local.js</code></td></tr></tbody></table><h3 id="常见项目的-gitignore-模板" tabindex="-1">常见项目的 .gitignore 模板 <a class="header-anchor" href="#常见项目的-gitignore-模板" aria-label="Permalink to &quot;常见项目的 .gitignore 模板&quot;">​</a></h3><p>不同技术栈需要忽略的文件不同。不需要从头写，去 <a href="https://www.toptal.com/developers/gitignore" target="_blank" rel="noreferrer">gitignore.io</a> 输入你的技术栈（如 <code>Node</code>、<code>Python</code>、<code>Java</code>），它会自动生成。</p><p>写好后记得 <code>git add .gitignore</code> 并提交——忽略规则本身应该被团队共享。</p><h2 id="已经提交的文件怎么忽略" tabindex="-1">已经提交的文件怎么忽略 <a class="header-anchor" href="#已经提交的文件怎么忽略" aria-label="Permalink to &quot;已经提交的文件怎么忽略&quot;">​</a></h2><p>如果一个文件已经被 Git 跟踪了，后来才加到 <code>.gitignore</code> 里——Git 还是会跟踪它。需要先让它&quot;停止被跟踪&quot;：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 文件名</span></span></code></pre></div><p>然后提交。之后修改这个文件，<code>git status</code> 就不会再显示了。</p><h2 id="提交信息-怎么写才规范" tabindex="-1">提交信息：怎么写才规范 <a class="header-anchor" href="#提交信息-怎么写才规范" aria-label="Permalink to &quot;提交信息：怎么写才规范&quot;">​</a></h2><p>前面讲了提交信息要&quot;一读就懂&quot;。但团队协作时，光&quot;能读懂&quot;不够——还需要<strong>统一的格式</strong>，让 git log 看起来像一支团队写的，而不是一群人各写各的。</p><p>业界最通用的标准叫 <strong>Conventional Commits（约定式提交）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;scope&gt;): &lt;subject&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 例子</span></span>
<span class="line"><span>feat(login): 新增短信验证码登录功能</span></span>
<span class="line"><span>fix(payment): 修复微信支付回调签名校验失败的问题</span></span>
<span class="line"><span>docs(readme): 补充本地开发环境搭建说明</span></span></code></pre></div><h3 id="type-必填-表明改动类型" tabindex="-1">type：必填，表明改动类型 <a class="header-anchor" href="#type-必填-表明改动类型" aria-label="Permalink to &quot;type：必填，表明改动类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>type</th><th>含义</th><th>什么时候用</th></tr></thead><tbody><tr><td><code>feat</code></td><td>新功能</td><td>加了一个新页面、新接口、新组件</td></tr><tr><td><code>fix</code></td><td>修 bug</td><td>修复了一个线上或开发中的 bug</td></tr><tr><td><code>docs</code></td><td>文档</td><td>只改了 README、注释等文档</td></tr><tr><td><code>style</code></td><td>格式</td><td>空格、分号、换行，不影响代码逻辑</td></tr><tr><td><code>refactor</code></td><td>重构</td><td>优化代码结构，没加功能也没修 bug</td></tr><tr><td><code>perf</code></td><td>性能</td><td>做了性能优化</td></tr><tr><td><code>test</code></td><td>测试</td><td>添加或修改测试用例</td></tr><tr><td><code>chore</code></td><td>杂项</td><td>改了构建配置、依赖版本等</td></tr><tr><td><code>revert</code></td><td>回退</td><td>撤销之前的某次提交</td></tr><tr><td><code>build</code></td><td>构建</td><td>影响构建系统或外部依赖的改动</td></tr><tr><td><code>ci</code></td><td>持续集成</td><td>CI 配置文件和脚本的改动</td></tr></tbody></table><h3 id="scope-可选-和-subject-必填" tabindex="-1">scope（可选）和 subject（必填） <a class="header-anchor" href="#scope-可选-和-subject-必填" aria-label="Permalink to &quot;scope（可选）和 subject（必填）&quot;">​</a></h3><p><code>scope</code> 标明改动范围（如 <code>login</code>、<code>payment</code>、<code>readme</code>），可写可不写。<code>subject</code> 是简短描述，注意两点：</p><ul><li><strong>用中文还是英文</strong> — 团队统一就行，没有绝对标准</li><li><strong>不要超过 50 个字</strong> — 太长了就不是&quot;简短描述&quot;了</li></ul><h3 id="正确-vs-错误示范" tabindex="-1">正确 vs 错误示范 <a class="header-anchor" href="#正确-vs-错误示范" aria-label="Permalink to &quot;正确 vs 错误示范&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ❌ 没有 type</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;新增了登录功能&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅ 有 type，一目了然</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;feat(login): 新增短信验证码登录功能&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ❌ type 不明确</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;update code&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅ 明确是修复还是功能</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fix(api): 修复用户列表接口空指针异常&quot;</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ol><li><strong>不该提交的文件写到 <code>.gitignore</code></strong> — <code>node_modules/</code>、<code>.env</code>、<code>.DS_Store</code>，第一行就该写</li><li><strong>已跟踪的文件加 .gitignore 没用</strong> — 先 <code>git rm --cached</code> 让它停止跟踪</li><li><strong>提交信息用约定式提交</strong> — <code>type(scope): subject</code>，团队统一格式，git log 清爽可读</li></ol><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>在项目中创建 <code>.gitignore</code>，忽略 <code>node_modules/</code>、<code>.env</code>、<code>*.log</code>，提交并确认之后这些文件不会被 git status 显示</li><li>故意创建一个已被跟踪的文件，尝试加到 <code>.gitignore</code>，观察是否还有效。然后用 <code>git rm --cached</code> 解决</li><li>把最近几次提交信息改成约定式格式（<code>feat</code>/<code>fix</code>/<code>docs</code>/<code>chore</code>）</li><li>去 github.com 找几个知名开源项目，看看他们的提交历史用的是不是约定式提交</li></ol>`,33)])])}const k=a(i,[["render",d]]);export{g as __pageData,k as default};
